mapper.sql:
WHERE 1=1

  AND i.factory_code IS NOT NULL


      AND 1=0

        AND (i.factory_code IN #{x}
          OR (i.factory_code IS NULL AND i.bill_no IN (SELECT l.bill_no FROM sn_bill_ledger l WHERE l.org_code IN
            #{x})))




AND i.customer_code = #{f.customerCode}
AND i.pi_no = #{f.pi}
AND i.bill_no = #{f.billNo}
AND i.length_text = #{f.length}
AND i.sn = #{f.sn}
AND i.material_code = #{f.materialCode}

  AND i.suspend IS NOT NULL
  AND i.status = #{f.status}


  AND i.seq_pi_no = #{f.rangePi}
  AND i.seq_dec >= #{f.rangeLo}
  AND i.seq_dec <= #{f.rangeHi}

mapper.select:
SELECT EXISTS(SELECT 1 FROM sn_item WHERE pi_no = #{pi}

    AND 1=0
    AND factory_code IN #{x}
  )

SELECT i.id, i.sn, i.rule_version_id, i.seq_dec, i.seq_pi_no, i.pi_no, i.bill_no, i.bill_seq, i.material_code, i.length_text, i.customer_code, i.factory_code, i.status, i.suspend, i.created_at, i.attach_no FROM sn_item i ORDER BY i.pi_no, TRIM(i.attach_no) = '', TRIM(i.attach_no) NOT REGEXP '^[0-9]+([.][0-9]+)?$', CASE WHEN TRIM(i.attach_no) REGEXP '^[0-9]+([.][0-9]+)?$' THEN CAST(TRIM(i.attach_no) AS DECIMAL(65, 30)) ELSE 0 END, TRIM(i.attach_no),
i.seq_pi_no, i.seq_dec, i.id i.bill_no, i.bill_seq, i.seq_pi_no, i.seq_dec, i.id
LIMIT #{offset}, #{size}
